 orders:{label:'Aufträge & Shops',single:'Bestellung',description:'Portalaufträge und Shopbestellungen mit eindeutigen Quellenreferenzen.',icon:'shop',lines:true,fields:[short('name','Bestellbezeichnung'),reference('customer_id','Kunde','customers'),short('source','Shop / Quelle'),short('external_id','Bestellnummer im Shop'),fieldSpec('ordered_date','Bestelldatum','date'),note('notes','Notizen')]},
