function wsReadFields(form,resource){const values=Object.fromEntries(new FormData(form));const result={};for(const f of wsSchemas[resource].fields){if(f.type==='reference'&&!f.optional&&!values[f.name])throw new Error(`${f.label}: einen Datensatz aus der Suche auswählen.`);result[f.name]=['money','signed-money','percent'].includes(f.type)?Math.round(Number(values[f.name])*100):f.name==='core_revision'?Number(values[f.name]):values[f.name];}if(wsSchemas[resource].lines){result.lines=[...form.querySelectorAll('.line-row')].map(wsReadLine);}return result;}
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.id.startsWith('ws-'))return;event.preventDefault();
 if(form.id==='ws-search'){wsState.query=new FormData(form).get('q');wsState.page=0;wsState.cursors=[0];await wsList(state.view);return;}
 const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;const errorElement=form.querySelector('.form-error');if(errorElement)errorElement.textContent='';
 try{const fields=Object.fromEntries(new FormData(form));let response;
 if(form.id==='ws-commerce-accept'){await command(`/api/v1/commerce/offers/${form.dataset.id}/accept`,'POST',{version:Number(form.dataset.version),acceptance_reference:fields.acceptance_reference});$('#editor').close();$('#editor').classList.remove('wide');await load();render();toast('Angebot angenommen und Auftrag erstellt.');return;}
 if(form.id==='ws-editor'){const data=wsReadFields(form,form.dataset.resource);response=await command(wsRoute(form.dataset.resource)+(form.dataset.id?`/${form.dataset.id}`:''),form.dataset.id?'PUT':'POST',form.dataset.id?{version:Number(form.dataset.version),fields:data}:data);}
 else if(form.id==='ws-briefing-handoff'){await command(`${wsRoute('briefings')}/${form.dataset.id}/handoff`,'POST',{version:Number(form.dataset.version),revision:Number(form.dataset.revision),note:fields.note});await wsList('briefings');await wsDetail('briefings',form.dataset.id);toast('Manuelle Übergabe erfasst.');return;}
 else if(form.id==='ws-organization'){await command('/api/v1/settings/organization','PUT',{version:Number(form.dataset.version),fields});}
 else if(['ws-allocation','ws-cancel','ws-published'].includes(form.id)){const action=form.id==='ws-allocation'?'allocate':form.id==='ws-cancel'?'cancel':'status';if(action==='allocate')fields.amount_cents=Math.round(Number(fields.amount_cents)*100);if(action==='status')fields.status='published';await command(`${wsRoute(form.dataset.resource)}/${form.dataset.id}/${action}`,'POST',{version:Number(form.dataset.version),...fields});}
 else if(form.id==='ws-period'){await command('/api/v1/finance/periods','POST',{period:form.dataset.period,closed:form.dataset.closed==='false',reason:fields.reason});}
 else if(form.id==='ws-thresholds'){await api('/api/v1/finance/thresholds',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({minimum_liquidity_cents:Math.round(Number(fields.minimum)*100),maximum_overdue_cents:Math.round(Number(fields.maximum)*100)})});}
 else if(form.id==='ws-journal'){const amount=Math.round(Number(fields.amount)*100);await command('/api/v1/finance/journal','POST',{booking_date:fields.booking_date,description:fields.description,lines:[{account:fields.debit_account,debit_cents:amount,credit_cents:0},{account:fields.credit_account,debit_cents:0,credit_cents:amount}]});}
 else if(form.id==='ws-finance-assignment'){await command(`${wsRoute(form.dataset.resource)}/${form.dataset.id}/${form.dataset.action}`,'POST',{version:Number(form.dataset.version),...fields,amount_cents:Math.round(Number(fields.amount_cents)*100)});}
 else if(form.id==='ws-connection'){await command(`/api/v1/connections/${form.dataset.connection}/jobs`,'POST',{operation:fields.operation,input:JSON.parse(fields.payload)});}
 else if(form.id==='ws-user'){const body=form.dataset.id?{name:fields.name,role:fields.role,disabled:fields.disabled==='yes',version:Number(form.dataset.version)}:fields;await api('/api/v1/access/users'+(form.dataset.id?`/${form.dataset.id}`:''),{method:form.dataset.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});form.reset();}
 else if(form.id==='ws-password'){await api('/api/v1/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(fields)});form.reset();location.reload();return;}
 else if(form.id==='ws-token'){const response=await api('/api/v1/access/tokens',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fields.name,expires_in_days:Number(fields.days),scopes:fields.scopes.split(',').map(s=>s.trim()).filter(Boolean)})});form.reset();openDialog('Agentenzugang erstellt',`<p>Kopiere diesen Zugang jetzt in deinen Secret-Provider. Er wird nur einmal angezeigt.</p><label>Token<input readonly class="token-value" value="${esc(response.token)}" autocomplete="off"></label><div class="form-actions"><button class="button primary" data-close>Erledigt</button></div>`);$('.token-value').select();await wsAccess();return;}
 $('#editor').close();$('#editor').classList.remove('wide');await load();render();toast('Gespeichert.');
 }catch(error){if(errorElement)errorElement.textContent=error.message;else toast(error.message);if(button)button.disabled=false;}
});
